    return f"Row {number}: {names}"

def _check_inputs(students: Sequence[Student], seats_per_row: int) -> None:
    if seats_per_row < 1:
        raise ProjectError("seats per row must be at least one")
    if not students:
        raise ProjectError("no students to seat")

def _split(items: Sequence[Student], size: int) -> List[Sequence[Student]]:
    return [items[start:start + size] for start in range(0, len(items), size)]

# ---
def seating_rows(students: Sequence[Student], seats_per_row: int) -> List[str]:
    """One line of text per row, students ordered by last name."""
    _check_inputs(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    chunks = _split(ordered, seats_per_row)
    return [_format_row(index, chunk) for index, chunk in enumerate(chunks, 1)]

