from rosterkit.errors import ProjectError

def _cells(student: Student) -> tuple:
    if not student.email:
        raise ProjectError(f"no email for {student.display_name}")
    return (student.display_name, student.section, student.email)

def _pad(cells: tuple, widths: list) -> str:
    return "  ".join(c.ljust(w) for c, w in zip(cells, widths)).rstrip()

# ---
def format_contacts(students) -> list:
    if not students:
        raise ProjectError("no students to list")
    rows = [_cells(s) for s in sorted(students, key=lambda s: s.display_name)]
    widths = [max(len(r[i]) for r in rows) for i in range(3)]
    return [_pad(r, widths) for r in rows]

